{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "General warranty cap can be negotiated commercially, but carve out from it"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PARTIAL",
      "evidence": "If retained, use a tipping/first-dollar basket rather than deductible basket, lower it if risk allocation warrants"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "General business warranties: seek 24 months minimum."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title/capacity/authority claims should be uncapped (or capped at purchase price) and survive for at least the statutory limitation period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve out fundamental warranties, Tax Covenant, specific indemnities, Completion/payment obligations, fraud, wilful misconduct, deliberate concealment, equitable relief and non-excludable statutory rights."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete general disclosure of the data room/public records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject blanket data-room/public-record disclosure and constructive Buyer knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make satisfactory written Bluefen consent, with all conditions fulfilled or irrevocably waived, a Buyer-benefit condition precedent to Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "This is a Completion deliverable, not a post-Completion promise."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require Seller to bear/pay all Completion bonuses and all related payroll tax, super, leave and on-costs."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Resolve Ironquay IP ownership before Completion, or obtain a broad stand-alone indemnity plus a meaningful escrow/holdback."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Escalate and investigate the privacy/export incident; require tailored protection and consider a holdback."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "If commitments were entered into outside agreed ordinary-course parameters, treat them as leakage/price adjustment or obtain indemnity."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Confine caps, time limits, thresholds, exclusive remedy and non-reliance provisions to ordinary warranty claims only."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require title warranties, current ASIC extract, register, share certificates (if applicable), board/member approvals, releases of all share security"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Obtain a stand-alone Tax Covenant/indemnity"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

